import{_ as i,o,c as s,a2 as a}from"./chunks/framework.D0_YsCyK.js";const p=JSON.parse('{"title":"O11 — Passkey 与系统配置功能审计","description":"","frontmatter":{},"headers":[],"relativePath":"audit/O11-passkey-config.md","filePath":"audit/O11-passkey-config.md","lastUpdated":1792449669000}'),n={name:"audit/O11-passkey-config.md"};function d(t,e,l,c,r,h){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="o11-—-passkey-与系统配置功能审计" tabindex="-1">O11 — Passkey 与系统配置功能审计 <a class="header-anchor" href="#o11-—-passkey-与系统配置功能审计" aria-label="Permalink to &quot;O11 — Passkey 与系统配置功能审计&quot;">​</a></h1><p><strong>审计员</strong>：Passkey/配置专项 <strong>日期</strong>：2026-10-20 <strong>范围</strong>：<code>go-backend/internal/http/handler/passkey.go</code>、<code>repository_passkey.go</code>、<code>model/passkey.go</code>、配置读写（<code>handler.go:517-600,1107-1210</code>、<code>config_access.go</code>、<code>repo/config_policy.go</code>）、前端 <code>passkey-manager.tsx</code>、<code>utils/passkey.ts</code>、登录页 passkey 入口 <strong>参考</strong>：<code>doc/guide/passkey.md</code><strong>结论</strong>：P0 0 / P1 0 / <strong>P2 1</strong> / <strong>P3 3</strong>。核心 WebAuthn 流程（challenge 单次性/过期/origin 绑定/可发现登录归属校验/克隆检测）实现正确，3 个合约测试 + 1 个单元测试全部通过。</p><hr><h2 id="p2" tabindex="-1">P2 <a class="header-anchor" href="#p2" aria-label="Permalink to &quot;P2&quot;">​</a></h2><h3 id="o11-p2-1-passkeyloginbegin-无限流-可被洪水填满-challenge-池导致通行证密钥功能-dos" tabindex="-1">O11-P2-1：<code>passkeyLoginBegin</code> 无限流，可被洪水填满 challenge 池导致通行证密钥功能 DoS <a class="header-anchor" href="#o11-p2-1-passkeyloginbegin-无限流-可被洪水填满-challenge-池导致通行证密钥功能-dos" aria-label="Permalink to &quot;O11-P2-1：`passkeyLoginBegin` 无限流，可被洪水填满 challenge 池导致通行证密钥功能 DoS&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/passkey.go</code><ul><li><code>putPasskeyCeremony</code>（约 L84–101）：<code>passkeyPending</code> 上限 1000，满则返回 <code>&quot;&quot;, false</code> → 调用方返回&quot;无法创建通行证密钥挑战&quot;</li><li><code>passkeyLoginBegin</code>（约 L280–305）：公开接口（<code>middleware/auth.go:126</code> 在 <code>shouldSkip</code> 中放行），<strong>全程未调用 <code>checkLoginRateLimit</code></strong></li></ul></li><li><strong>复现</strong>：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">seq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://panel/api/v1/user/passkey/login/begin&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">done</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 此后合法用户的 begin 请求返回 code != 0（&quot;无法创建通行证密钥挑战&quot;），持续到池内 challenge 过期（TTL 2 分钟）</span></span></code></pre></div></li><li><strong>分析</strong>：池子按 2 分钟 TTL 自然过期 + 每次 <code>put</code> 时顺带清扫过期项，因此攻击者需以约 ≥8.3 req/s 持续发送即可长期占满。密码登录不受影响（独立限流 <code>handler.go:400</code>），故定为 P2 而非 P1。</li><li><strong>关联</strong>：K-auth.md 的 K-005 已指出 <code>passkeyLoginFinish</code> 无限流；本条是 <code>begin</code> 侧的池耗尽向量，两处应一并加限流。</li><li><strong>建议</strong>：对 <code>passkeyLoginBegin</code>/<code>passkeyLoginFinish</code> 复用 <code>checkLoginRateLimit</code>（或独立的 IP 桶）。</li></ul><hr><h2 id="p3" tabindex="-1">P3 <a class="header-anchor" href="#p3" aria-label="Permalink to &quot;P3&quot;">​</a></h2><h3 id="o11-p3-1-删除通行证密钥不吊销已签发的-jwt-会话" tabindex="-1">O11-P3-1：删除通行证密钥不吊销已签发的 JWT 会话 <a class="header-anchor" href="#o11-p3-1-删除通行证密钥不吊销已签发的-jwt-会话" aria-label="Permalink to &quot;O11-P3-1：删除通行证密钥不吊销已签发的 JWT 会话&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/passkey.go</code> → <code>passkeyDelete</code>（约 L390–430）</li><li><strong>现象</strong>：删除密钥后，该用户此前通过任何方式（密码或通行证密钥）登录签发的 token 在过期前（最长 7 天）仍然有效。</li><li><strong>说明</strong>：与改密不吊销旧 token 的现有设计一致（M-05 用 <code>PwdChangeRequired</code> claim 做软控制），属已知权衡；但密钥被盗用的场景下，用户删除密钥时期望&quot;踢掉盗用者会话&quot;，当前行为不符合该直觉。定 P3。</li></ul><h3 id="o11-p3-2-updateconfigs-批量-与-updatesingleconfig-单个-校验不一致-且批量无事务" tabindex="-1">O11-P3-2：<code>updateConfigs</code>（批量）与 <code>updateSingleConfig</code>（单个）校验不一致，且批量无事务 <a class="header-anchor" href="#o11-p3-2-updateconfigs-批量-与-updatesingleconfig-单个-校验不一致-且批量无事务" aria-label="Permalink to &quot;O11-P3-2：`updateConfigs`（批量）与 `updateSingleConfig`（单个）校验不一致，且批量无事务&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/handler.go:1107-1154</code> vs <code>1156-1199</code></li><li><strong>现象 1</strong>：<code>updateSingleConfig</code> 拒绝空值（<code>if value == &quot;&quot; &amp;&amp; name != &quot;app_logo&quot; &amp;&amp; name != &quot;app_favicon&quot;</code> → &quot;配置值不能为空&quot;，L1184），但 <code>updateConfigs</code> 循环内无此检查，可经批量接口写入空值。</li><li><strong>现象 2</strong>：批量循环逐个 <code>UpsertConfig</code>，中途某个 key 校验失败（<code>normalizeAndValidateConfigValue</code>）时，已写入的 key 不回滚 → 配置处于部分更新状态。</li><li><strong>影响</strong>：仅管理员可调用（中间件 <code>requiresAdmin</code>，<code>auth.go:203</code>），属管理面健壮性问题。定 P3。</li><li><strong>建议</strong>：抽取公共校验函数；批量改用 <code>repo.UpsertConfigs</code> 并在事务内先全量校验再写入。</li></ul><h3 id="o11-p3-3-getconfigs-中变量-isadmin-实际含义是-已认证-命名误导" tabindex="-1">O11-P3-3：<code>getConfigs</code> 中变量 <code>isAdmin</code> 实际含义是&quot;已认证&quot;，命名误导 <a class="header-anchor" href="#o11-p3-3-getconfigs-中变量-isadmin-实际含义是-已认证-命名误导" aria-label="Permalink to &quot;O11-P3-3：`getConfigs` 中变量 `isAdmin` 实际含义是&quot;已认证&quot;，命名误导&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/handler.go:568-572</code><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">claims, isAdmin </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ctxClaims.(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Claims</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> !</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">isAdmin </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> claims.RoleID </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    cfgMap </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> repo.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">FilterSensitiveConfigs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(cfgMap)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><strong>分析</strong>：<code>isAdmin</code> 实为类型断言是否成功（即是否已登录），真正的管理员判断是 <code>claims.RoleID != 0</code>。当前逻辑正确（未登录或非管理员都过滤敏感项），但变量名与含义不符，后续维护者极易误读为&quot;已是管理员&quot;而改错分支。定 P3（代码卫生）。</li></ul><hr><h2 id="验证通过-附证据" tabindex="-1">验证通过（附证据） <a class="header-anchor" href="#验证通过-附证据" aria-label="Permalink to &quot;验证通过（附证据）&quot;">​</a></h2><h3 id="pk-01-challenge-单次性与过期" tabindex="-1">PK-01 challenge 单次性与过期 <a class="header-anchor" href="#pk-01-challenge-单次性与过期" aria-label="Permalink to &quot;PK-01 challenge 单次性与过期&quot;">​</a></h3><ul><li><code>putPasskeyCeremony</code> 生成 32 字节随机 <code>sessionId</code>（<code>crypto/rand</code>）；<code>takePasskeyCeremony</code>/<code>takePasskeyLoginCeremony</code> 先 <code>delete</code> 再校验 → 失败也消耗，防重放。</li><li>过期检查 <code>time.Now().After(c.session.Expires)</code>，TTL=2 分钟（<code>passkeyTTL</code>）；<code>webauthn.Config</code> 的 Login/Registration Timeout 均 <code>Enforce: true</code>。</li><li>单元测试 <code>TestPasskeyChallengeExpiresAndIsSingleUse</code> 通过（实测：<code>go test -run TestPasskey</code> ✅）。</li></ul><h3 id="pk-02-origin-绑定-fail-closed" tabindex="-1">PK-02 origin 绑定，fail-closed <a class="header-anchor" href="#pk-02-origin-绑定-fail-closed" aria-label="Permalink to &quot;PK-02 origin 绑定，fail-closed&quot;">​</a></h3><ul><li><code>passkeyConfig()</code>（<code>passkey.go:41-72</code>）：严格解析 <code>FLVX_WEBAUTHN_ORIGIN</code>，拒绝带 path/query/userinfo、含空格、非 https（localhost/127.0.0.1 允许 http）；<code>RPOrigins=[origin]</code>，<code>RPID=hostname</code>。</li><li>ceremony 在 begin 时记录 <code>origin</code>，finish 时用<strong>重新解析</strong>的 env origin 比对（<code>c.origin != origin</code> → 拒绝）。配置非法时 <code>wa==nil</code> → 所有 begin/finish 直接拒绝，且已存 ceremony 的 origin 必然不匹配空字符串 → fail-closed。</li><li>与手册&quot;未设置或设置错误时拒绝新的绑定和登录&quot;一致。</li></ul><h3 id="pk-03-可发现登录的归属校验-防跨账号冒用" tabindex="-1">PK-03 可发现登录的归属校验（防跨账号冒用） <a class="header-anchor" href="#pk-03-可发现登录的归属校验-防跨账号冒用" aria-label="Permalink to &quot;PK-03 可发现登录的归属校验（防跨账号冒用）&quot;">​</a></h3><ul><li><code>passkeyLoginFinish</code> 的 <code>FinishPasskeyLogin</code> 回调（<code>passkey.go:310-328</code>）：用 credential ID 查库得 owner，再比对 <code>userHandle</code>（8 字节 big-endian userID）与 owner 的 <code>WebAuthnID()</code> 是否一致；注释明确&quot;supplied userHandle cannot select another account&quot;。</li><li>合约测试 <code>TestPasskeyDiscoverableLoginAndOwnership</code> 通过 ✅（含跨账号冒用负例）。</li></ul><h3 id="pk-04-克隆检测与-sign-counter-cas" tabindex="-1">PK-04 克隆检测与 sign counter CAS <a class="header-anchor" href="#pk-04-克隆检测与-sign-counter-cas" aria-label="Permalink to &quot;PK-04 克隆检测与 sign counter CAS&quot;">​</a></h3><ul><li><code>credential.Authenticator.CloneWarning</code> → 拒绝登录（<code>passkey.go:336</code>）。</li><li><code>UpdatePasskeyCredential</code> 用 <code>WHERE credential_json = oldJSON</code> 做 compare-and-swap（<code>repository_passkey.go:40-45</code>），并发断言不会用旧 counter 覆盖。</li></ul><h3 id="pk-05-注册-删除需当前密码-仅能操作自己" tabindex="-1">PK-05 注册/删除需当前密码 + 仅能操作自己 <a class="header-anchor" href="#pk-05-注册-删除需当前密码-仅能操作自己" aria-label="Permalink to &quot;PK-05 注册/删除需当前密码 + 仅能操作自己&quot;">​</a></h3><ul><li><code>passkeyRegisterBegin</code>/<code>passkeyDelete</code> 均校验 <code>security.VerifyPassword(user.Pwd, req.Password)</code>；<code>userID</code> 取自 JWT（<code>userIDFromRequest</code>），<code>DeletePasskey(userID, id)</code> 带 user_id 条件 → 不能删别人的密钥。</li><li>停用账号（<code>Status != 1</code>）在 register/begin/login-finish 三处均被拒绝。</li></ul><h3 id="pk-06-登录后-token-与-m-05-改密闭环" tabindex="-1">PK-06 登录后 token 与 M-05 改密闭环 <a class="header-anchor" href="#pk-06-登录后-token-与-m-05-改密闭环" aria-label="Permalink to &quot;PK-06 登录后 token 与 M-05 改密闭环&quot;">​</a></h3><ul><li><code>passkeyLoginFinish</code> 复用 <code>isStoredDefaultPassword</code> → 默认口令签发受限 token（<code>GenerateTokenAtWithPwdChangeRequired</code>），与密码登录一致；返回 <code>requirePasswordChange</code> 字段。</li></ul><h3 id="pk-07-公开面最小化" tabindex="-1">PK-07 公开面最小化 <a class="header-anchor" href="#pk-07-公开面最小化" aria-label="Permalink to &quot;PK-07 公开面最小化&quot;">​</a></h3><ul><li><code>shouldSkip</code> 仅放行 <code>status</code>/<code>login/begin</code>/<code>login/finish</code>（<code>auth.go:126</code>）；<code>register/*</code>、<code>list</code>、<code>delete</code> 均需 JWT。<code>passkeyList</code> 返回 id/name/createdAt/lastUsedAt，不泄露 <code>credential_json</code>。</li></ul><h3 id="pk-08-配置读写权限" tabindex="-1">PK-08 配置读写权限 <a class="header-anchor" href="#pk-08-配置读写权限" aria-label="Permalink to &quot;PK-08 配置读写权限&quot;">​</a></h3><ul><li><code>getPublicConfigByName</code> 仅允许 <code>IsPublicConfigKey</code>（<code>config_access.go:27</code>）；<code>getConfigByName</code> 对敏感 key 要求 admin（<code>handler.go:532</code>），未登录只能读公开 key（<code>handler.go:537</code>）；<code>updateConfigs</code>/<code>updateSingleConfig</code> 在 <code>requiresAdmin</code> 中间件（<code>auth.go:203</code>）+ handler 内二次检查敏感/系统管理 key（纵深防御）。</li><li><code>normalizeAndValidateConfigValue</code> 对 <code>app_logo</code>/<code>app_favicon</code> 做 PNG data-URL 前缀 + base64 合法性 + 大小上限校验；监控类 key 做枚举/数值归一化。</li></ul><h3 id="pk-09-配置热更新" tabindex="-1">PK-09 配置热更新 <a class="header-anchor" href="#pk-09-配置热更新" aria-label="Permalink to &quot;PK-09 配置热更新&quot;">​</a></h3><ul><li>DB 配置均为按请求 <code>GetConfigByName</code> 读取（<code>handler.go</code> 等 15+ 处），无启动时缓存 → <strong>改配置无需重启</strong>；<code>updateConfigs</code>/<code>updateSingleConfig</code> 内显式触发 <code>notifyTunnelQualityConfigChanged</code>（tunnel-quality 探针）与 <code>onLatencyConfigChanged</code>（延迟探测池）热生效。</li><li><strong>例外</strong>：通行证密钥 origin 取自环境变量 <code>FLVX_WEBAUTHN_ORIGIN</code>（<code>passkeyConfig()</code> 每次请求重读 env），改值需重建后端容器 —— 与 <code>doc/guide/passkey.md</code> 步骤 2 的说明一致，属已文档化的设计。</li></ul><h3 id="pk-10-合约测试" tabindex="-1">PK-10 合约测试 <a class="header-anchor" href="#pk-10-合约测试" aria-label="Permalink to &quot;PK-10 合约测试&quot;">​</a></h3><ul><li><code>go test ./tests/contract/ -run TestPasskey -count=1</code>：3/3 通过（<code>TestPasskeyConfigurationFailsClosedAndPasswordLoginStillWorks</code>、<code>TestPasskeyRegistrationAndOwnership</code>、<code>TestPasskeyDiscoverableLoginAndOwnership</code>）。</li></ul><hr><h2 id="未能验证-需人工-真机" tabindex="-1">未能验证（需人工/真机） <a class="header-anchor" href="#未能验证-需人工-真机" aria-label="Permalink to &quot;未能验证（需人工/真机）&quot;">​</a></h2><ol><li>真实 authenticator 的完整 WebAuthn ceremony（注册+登录），含 resident key 要求 <code>ResidentKeyRequirementRequired</code> 在各类设备上的表现 —— 无浏览器/硬件环境，标注未验证。</li><li>前端登录页&quot;选择通行证密钥登录&quot;按钮的实际渲染与 <code>isSecureContext</code> 分支 —— 仅代码走读（<code>pages/index.tsx:282-287</code>、<code>utils/passkey.ts</code> 的 base64url 编解码经核对符合规范：<code>atob</code> 对合法无填充输入的 <code>length%4==2/3</code> 情况按 WHATWG 规范可正常解码）。</li><li>多后端实例部署时的 challenge 共享 —— 手册已声明&quot;只保存在后端内存中…请保持单个后端实例&quot;，属已知限制。</li></ol><hr><h2 id="备注-不计入缺陷" tabindex="-1">备注（不计入缺陷） <a class="header-anchor" href="#备注-不计入缺陷" aria-label="Permalink to &quot;备注（不计入缺陷）&quot;">​</a></h2><ul><li><code>passkeyStatus</code> 公开返回 <code>enabled</code> 布尔值：轻微信息泄露（暴露管理员是否配置了 passkey），但登录页渲染依赖此接口，为功能必需。</li><li>单用户可注册的密钥数量无上限：每次注册需密码 + 完整 ceremony，自限速，不构成问题。</li><li>通行证密钥登录绕过 Cloudflare Turnstile：手册明确为设计意图（&quot;不依赖 Cloudflare Turnstile&quot;），且需物理设备签名，不视为漏洞。</li></ul>',42)])])}const k=i(n,[["render",d]]);export{p as __pageData,k as default};
